class Solution {
  public long maxWeight(int[] pizzas) {
    java.util.Arrays.sort(pizzas);
    int n = pizzas.length, days = n / 4, odd = (days + 1) / 2, even = days / 2;
    long total = 0;
    // odd days eat the largest pizza of their group: give them the overall largest ones
    for (int i = n - odd; i < n; i++) total += pizzas[i];
    // even days eat the second largest: each one spends a big pizza to gain the next one down
    for (int d = 0, idx = n - 1 - odd; d < even; d++, idx -= 2) total += pizzas[idx - 1];
    return total;
  }
}
